-- Paket ABT "abt-x9-pihak-banyak-21okt" (21 Okt 2026): identitas pihak banyak (Pemohon/Penggugat, Termohon/Tergugat, Turut Tergugat, pihak intervensi) tercetak lengkap sampai pihak terakhir.
-- 10 variabel baru (3507-3516), 6 baris diubah (7047, 7048, 7054, 7097, 7098, 8710), 6 fungsi tersimpan baru (isian_rtf_romawi, isian_rtf_tanggal, isian_rtf_pihak_utama, isian_rtf_pihak_nama, isian_rtf_pihak_urutan, isian_rtf_pihak_tambahan).
-- PERIKSA: tiap variabel baru dan baris diubah persis isi paket; fungsi ada dan benar; baris terakhir "SEMUA COCOK".
SELECT 'var 3507 baru' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=3507 AND MD5(nama)='c30feb150627afbfacb38643b1133363' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='baf2d3e4bad5d739a2d206c1796649f4' AND default_data IS NULL)) AS cocok;
