SELECT 'fungsi ada' AS butir, IF((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name IN ('isian_rtf_romawi','isian_rtf_tanggal','isian_rtf_pihak_utama','isian_rtf_pihak_nama','isian_rtf_pihak_urutan','isian_rtf_pihak_tambahan') AND routine_comment LIKE 'X9:%') = 6, 1, 0) AS cocok;
SELECT 'fungsi romawi' AS butir, IF(isian_rtf_romawi(4) = 'IV' AND isian_rtf_romawi(9) = 'IX' AND isian_rtf_romawi(14) = 'XIV' AND isian_rtf_romawi(29) = 'XXIX' AND isian_rtf_romawi(49) = 'XLIX' AND isian_rtf_romawi(32) = 'XXXII' AND isian_rtf_romawi(1994) = 'MCMXCIV' AND isian_rtf_romawi(0) = '' AND isian_rtf_romawi(4000) = '', 1, 0) AS cocok;
SELECT 'fungsi tanggal' AS butir, IF(isian_rtf_tanggal('1970-10-01') = '01 Oktober 1970' AND isian_rtf_tanggal('2026-11-25') = '25 November 2026' AND isian_rtf_tanggal(NULL) = '' AND isian_rtf_tanggal('1899-12-31') = '', 1, 0) AS cocok;
SELECT 'fungsi perkara kosong' AS butir, IF(isian_rtf_pihak_utama(0, 1, 1, 'a', 'b') = '' AND isian_rtf_pihak_utama(0, 2, 1, 'a', 'b') = '' AND isian_rtf_pihak_utama(0, 3, 1, 'a', 'b') = '' AND isian_rtf_pihak_nama(0, 1, 1, 'a') = '' AND isian_rtf_pihak_nama(0, 2, 1, 'a') = '' AND isian_rtf_pihak_urutan(0, 1, 'a') = '' AND isian_rtf_pihak_urutan(0, 2, 'a') = '' AND isian_rtf_pihak_tambahan(0, 4) = '' AND isian_rtf_pihak_tambahan(0, 3) = '' AND isian_rtf_pihak_tambahan(0, 5) = '', 1, 0) AS cocok;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=3507 AND MD5(nama)='c30feb150627afbfacb38643b1133363' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='baf2d3e4bad5d739a2d206c1796649f4' AND default_data IS NULL) OR (no_var=3508 AND MD5(nama)='c75366f63763509c0583a293288252e1' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='3b6e463560415f360944d7df31c32e1d' AND default_data IS NULL) OR (no_var=3509 AND MD5(nama)='72c2cf30e4ce051090ed93e05dae14db' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='1745cfe571ee689834470b37f65495f4' AND default_data IS NULL) OR (no_var=3510 AND MD5(nama)='c73cf1d4c510fc03a1b0fb64b23c167b' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='3ddd922432351c7b9cd00f6a912167bf' AND default_data IS NULL) OR (no_var=3511 AND MD5(nama)='7286508becf948c510bb03f3c757d573' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='1039e8b8a5a1c2f5f1ce4a803bf09303' AND default_data IS NULL) OR (no_var=3512 AND MD5(nama)='c695bdadaa21ddf644b964c9aabd246d' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='cbd1290efda8f064c63fab2313dfaf94' AND default_data IS NULL) OR (no_var=3513 AND MD5(nama)='fcc3803554a051e76f8375f453899829' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='9d46b848e10e11484a0679ad259a4690' AND default_data IS NULL) OR (no_var=3514 AND MD5(nama)='87329cb57166a6730333e51824bbe524' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='ce1f6ff60201d23e429164d800a1bc6a' AND default_data IS NULL) OR (no_var=3515 AND MD5(nama)='5fcb75b4192e084a9d3a0f7132a3f5f1' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='1fa659c52c36f9ab3c873785a7d67211' AND default_data IS NULL) OR (no_var=3516 AND MD5(nama)='8b16097b6c75c5f9fcd6b3360fb1b392' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='bc1d508d39fa788707fc207aae5bad58' AND default_data IS NULL) OR (no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='4768ceb89c86ce434e89654add897548') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='48b9f3ff7ec2039aa61707881ccaa4e0') OR (no_var=7054 AND MD5(nama)='6101d736b02e70ed32db103727097dd6' AND data_type='data_sql' AND MD5(sql_query)='fea7ab72cd98afb9503e70bf97c34534') OR (no_var=7097 AND MD5(nama)='6381b070ba833efd8b2872ed0667be82' AND data_type='data_sql' AND MD5(sql_query)='34861e8bbe329026885e141001b2eaa5') OR (no_var=7098 AND MD5(nama)='338fbfd71f0675334fb9c06d7e56812c' AND data_type='data_sql' AND MD5(sql_query)='063178271c53178f36fdb8dbb7979c67') OR (no_var=8710 AND MD5(nama)='5d820fcd9bfe5e681ec5d91f16755f40' AND data_type='data_sql' AND MD5(sql_query)='211d132dd75aad35808d205d785ceb1c'))) = 16 AND (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name IN ('isian_rtf_romawi','isian_rtf_tanggal','isian_rtf_pihak_utama','isian_rtf_pihak_nama','isian_rtf_pihak_urutan','isian_rtf_pihak_tambahan') AND routine_comment LIKE 'X9:%') = 6 AND isian_rtf_romawi(4) = 'IV' AND isian_rtf_romawi(9) = 'IX' AND isian_rtf_romawi(14) = 'XIV' AND isian_rtf_romawi(29) = 'XXIX' AND isian_rtf_romawi(49) = 'XLIX' AND isian_rtf_romawi(32) = 'XXXII' AND isian_rtf_romawi(1994) = 'MCMXCIV' AND isian_rtf_romawi(0) = '' AND isian_rtf_romawi(4000) = '' AND isian_rtf_tanggal('1970-10-01') = '01 Oktober 1970' AND isian_rtf_tanggal('2026-11-25') = '25 November 2026' AND isian_rtf_tanggal(NULL) = '' AND isian_rtf_tanggal('1899-12-31') = '' AND isian_rtf_pihak_utama(0, 1, 1, 'a', 'b') = '' AND isian_rtf_pihak_utama(0, 2, 1, 'a', 'b') = '' AND isian_rtf_pihak_utama(0, 3, 1, 'a', 'b') = '' AND isian_rtf_pihak_nama(0, 1, 1, 'a') = '' AND isian_rtf_pihak_nama(0, 2, 1, 'a') = '' AND isian_rtf_pihak_urutan(0, 1, 'a') = '' AND isian_rtf_pihak_urutan(0, 2, 'a') = '' AND isian_rtf_pihak_tambahan(0, 4) = '' AND isian_rtf_pihak_tambahan(0, 3) = '' AND isian_rtf_pihak_tambahan(0, 5) = '', 'SEMUA COCOK', 'TIDAK COCOK') AS hasil;
